// Parse active alerts from Firestore
const response = $input.first().json;
const results = [];

if (response.documents) {
  for (const doc of response.documents) {
    const fields = doc.fields;

    const nameParts = doc.name.split('/');
    const event_id = nameParts[nameParts.length - 1];

    const isActive = fields.isActive?.booleanValue || false;

    if (isActive) {
      const alert = {
        event_id: event_id,
        title: fields.title?.stringValue || "",
        description: fields.description?.stringValue || "",
        summary: fields.summary?.stringValue || "",
        severity: fields.severity?.stringValue || "medium",
        disasterType: fields.disasterType?.stringValue || "unknown",
        trustScore: fields.trustScore?.integerValue || 0,
        trustStatus: fields.trustStatus?.stringValue || "UNVERIFIED",
        verificationReason: fields.verificationReason?.stringValue || "",
        location: fields.location?.mapValue?.fields?.city?.stringValue || "Unknown",
        recommended_action: fields.ai_analysis?.mapValue?.fields?.recommended_action?.stringValue || "Stay safe and follow official instructions"
      };

      results.push({ json: alert });
    }
  }
}

return results;

// Parse all users from Firestore
const response = $input.first().json;
const results = [];

if (response.documents) {
  for (const doc of response.documents) {
    const fields = doc.fields;

    const nameParts = doc.name.split('/');
    const user_id = nameParts[nameParts.length - 1];

    const user = {
      user_id: user_id,
      chat_id: fields.telegramChatId?.stringValue || "", // ✅ FIXED
      name: fields.name?.stringValue || "User",
      phone: fields.phone?.stringValue || "",
      preferred_language: fields.preferredLanguage?.stringValue || "english" // also fixed naming
    };

    if (user.chat_id) {
      results.push({ json: user });
    }
  }
}

return results;

// CROSS JOIN: Each alert × Each user
const alerts = $('Parse Active Alerts').all();
const users = $('Parse All Users').all();

const output = [];

console.log('Alerts count:', alerts.length);
console.log('Users count:', users.length);

for (const alertItem of alerts) {
  const alert = alertItem.json;

  for (const userItem of users) {
    const user = userItem.json;

    // Skip if user has no chat_id
    if (!user.chat_id || user.chat_id === "") {
      console.log('Skipping user with no chat_id:', user.user_id);
      continue;
    }

    // Normalize language
    let lang = (user.preferred_language || 'english').toLowerCase();
    if (lang === 'en') lang = 'english';
    if (lang === 'hi') lang = 'hindi';
    if (lang === 'mr') lang = 'marathi';

    output.push({
      json: {
        // Alert data
        event_id: alert.event_id,
        title: alert.title,
        description: alert.description,
        summary: alert.summary,
        severity: alert.severity,
        disasterType: alert.disasterType,
        trustScore: alert.trustScore,
        trustStatus: alert.trustStatus,
        verificationReason: alert.verificationReason,
        location: alert.location,
        recommended_action: alert.recommended_action,
        // User data (merged)
        telegram_id: user.chat_id,
        user_name: user.name,
        language: lang
      }
    });
  }
}

console.log('Output items:', output.length);
return output;

