// Parse Groq response and prepare for Telegram
const groqResponse = $input.first().json;
const originalData = $('Prepare Messages for All Users').first().json;

let alertText = "";

if (groqResponse.choices && groqResponse.choices[0]) {
  alertText = groqResponse.choices[0].message.content;
} else {
  alertText = `🚨 ${originalData.disasterType.toUpperCase()} ALERT\n📍 ${originalData.location}\n⚠️ ${originalData.summary}\n🔍 Trust Score: ${originalData.trustScore}/100 (${originalData.trustStatus})`;
}

const finalMessage = `${alertText}\n\n---\n🔍 Verification: ${originalData.verificationReason}\n\n✅ Tap 'Understood' if you got this\n❓ Tap 'Not Clear' if confused\n🔄 Tap 'Re-Verify' for latest info`;

return [{
  json: {
    telegram_id: originalData.telegram_id,
    language: originalData.language,
    event_id: originalData.event_id,
    message: finalMessage,
    trustScore: originalData.trustScore,
    trustStatus: originalData.trustStatus
  }
}];
